        X[i] = x; Y[i] = y
        r = 0
        t = ts[i]
        for j in range(l):
            r, q = readline().split(); q = int(q)
            k = n_map[r]
            if P[k] <= q:
                continue
            t.append((k, P[k] - q))

    E = [[0]*N for i in range(N)]
    E1 = [0]*N
    for i in range(N):
        for j in range(i):
            E[i][j] = E[j][i] = abs(X[i] - X[j]) + abs(Y[i] - Y[j])
        E1[i] = abs(X[i]) + abs(Y[i])
