#include<cstdio>

const int N = 50;

char s[N + 2];
int n, m, a[N + 2][N + 2], tr[4][2] = { {0, 1}, {1, 0}, {0, -1}, {-1, 0} }, cnt;

bool in(int x, int y)
{
	return x >= 0 && x < n && y >= 0 && y < m;
}

bool sol(int x, int y, int d)
{
	if (!x && !y  && cnt == 4)
		return 1;
	if (!in(x, y) || !a[x][y])
		return 0;
	a[x][y] = 0;
	if ((!x || x == n - 1) && (!y || y == m - 1))
		cnt++;
	for (int i = 1; i >= -1; i--)
	{
		int t = (d + i + 4) % 4;
		if (sol(x + tr[t][0], y + tr[t][1], t))
			return 1;
	}
	if ((!x || x == n - 1) && (!y || y == m - 1))
		cnt--;
	return 0;
}

