{
	for (; scanf("%d%d", &n, &m) && (n || m); )
	{
		for (int i = 0; i < n; i++)
		{
			scanf("%s", s);
			for (int j = 0; j < m; j++)
				a[i][j] = s[j] == '.';
		}
		cnt = 0;
