    while l<r:
      if l&1:
        ansl=f(ansl,self.seg[l])
        l+=1
      if ~r&1:
        ansr=f(self.seg[r],ansr)
        r-=1
      l>>=1
      r>>=1
    if l==r:
      ansl=f(ansl,self.seg[l])
    return f(ansl,ansr)


